effect.shader:
// sanchezae_cc: Cinematic color correction
vec3 applyTint(vec3 color, vec3 shadows, vec3 highlights, float strength) {
    float lum = dot(color, vec3(0.299, 0.587, 0.114));
    vec3 tint = mix(shadows, highlights, smoothstep(0.2, 0.8, lum));
    return mix(color, tint, strength);
}
float vignetteMask(vec2 uv, float strength) {
    float d = distance(uv, vec2(0.5));
    return 1.0 - smoothstep(0.5-strength*0.5, 0.75-strength*0.5, d);
}
vec3 bloomPass(sampler2D tex, vec2 uv, float strength) {
    vec3 sum = vec3(0.0);
    float w = 0.0;
    for (int x = -2; x <= 2; ++x)
    for (int y = -2; y <= 2; ++y) {
        float k = exp(-float(x*x + y*y)/4.0);
        sum += texture2DCv(tex, uv + vec2(x, y)*0.003).rgb * k;
        w += k;
    }
    return mix(vec3(0.0), sum/w, strength);
}
vec3 clarityPass(sampler2D tex, vec2 uv, float strength) {
    vec3 orig = texture2DCv(tex, uv).rgb;
    vec3 sharp = orig * 2.0 - 0.25 * (
        texture2DCv(tex, uv + vec2(0.002,0)).rgb +
        texture2DCv(tex, uv - vec2(0.002,0)).rgb +
        texture2DCv(tex, uv + vec2(0,0.002)).rgb +
        texture2DCv(tex, uv - vec2(0,0.002)).rgb
    );
    return mix(orig, sharp, strength);
}
void main() {
    vec2 uv = acScreenNorm;
    vec4 src = texture2DCv(inputImg.texture, uv);
    // Clarity
    vec3 color = clarityPass(inputImg.texture, uv, clarity);
    // Contrast
    color = (color - 0.5) * contrast + 0.5;
    // Tint
    color = applyTint(color, shadowTint.rgb, highlightTint.rgb, tintStrength);
    // Bloom
    color += bloomPass(inputImg.texture, uv, bloom);
    // Vignette
    float vign = vignetteMask(uv, vignette);
    color *= vign;
    gl_FragColor = vec4(color, src.a);
}
